const body = $input.first().json.body || $input.first().json || {};
const s = v => (v === undefined || v === null) ? '' : String(v).trim();

const pageType = s(body.pageType).toLowerCase();
if (!['industry', 'solution'].includes(pageType)) {
  throw new Error(`pageType is required and must be "industry" or "solution". Received: "${s(body.pageType)}"`);
}
if (!s(body.h1)) {
  throw new Error('h1 is required. It is used verbatim as the page H1 and is never rewritten.');
}
if (!s(body.coreKeyword)) {
  throw new Error('coreKeyword is required.');
}

return [{ json: {
  taskId: s(body.taskId),
  brandId: s(body.brandId),
  userId: s(body.userId),
  callback_url: s(body.callback_url),

  pageType,
  h1: s(body.h1),
  coreKeyword: s(body.coreKeyword),
  secondaryKeywords: s(body.secondaryKeywords),
  targetLanguage: s(body.targetLanguage) || 'English',

  industry: s(body.industry),
  useCase: s(body.useCase),
  contentIdea: s(body.contentIdea),

  clientName: s(body.clientName),
  productDescription: s(body.productDescription),
  clientProof: s(body.clientProof),
  certifications: s(body.certifications),

  ctaRules: s(body.ctaRules),
  writingPreferences: s(body.writingPreferences),

  whitelistDomains: body.whitelistDomains ?? [],
  blacklistDomains: body.blacklistDomains ?? [],

  pineconeIndex: s(body.pineconeIndex),
  pineconeNamespace: s(body.pineconeNamespace)
} }];

const items = $input.all();

function clean(value, max = 255) {
  if (value === undefined || value === null) return '';
  return String(value).slice(0, max);
}

function makeTraceId() {
  try {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  } catch (error) {}
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const first = items[0]?.json || {};
const trace = first.trace || {};

const executionId = clean($execution.id);
const workflowId = clean($workflow.id);

const ctx = {
  createdAt: new Date().toISOString(),
  executionKey: `${workflowId}:${executionId}`,
  executionId,
  workflowId,
  workflowName: clean($workflow.name),
  taskId: clean(first.taskId),
  brandId: clean(first.brandId),
  userId: clean(first.userId),
  pageType: clean(first.pageType),
  coreKeyword: clean(first.coreKeyword),
  traceId: clean(trace.traceId) || makeTraceId()
};

try {
  $execution.customData.setAll({
    executionKey: ctx.executionKey,
    taskId: ctx.taskId,
    brandId: ctx.brandId,
    userId: ctx.userId,
    pageType: ctx.pageType,
    coreKeyword: ctx.coreKeyword,
    traceId: ctx.traceId
  });
} catch (error) {}

return [{ json: ctx }];

