={{ (() => {
  const parser = $('Brief Parser').first().json;

  const body = {
    query: $fromAI('query', 'A focused search query of 3 to 7 words to find authoritative information.', 'string'),
    search_depth: 'advanced',
    max_results: 5
  };

  const whitelist = Object.keys(parser).filter(k => k.startsWith('whiteLink') && parser[k]).map(k => parser[k]);
  const blacklist = Object.keys(parser).filter(k => k.startsWith('blackLink') && parser[k]).map(k => parser[k]);

  if (whitelist.length > 0) body.include_domains = whitelist;

  const SOCIAL = ['linkedin.com', 'youtube.com', 'youtu.be', 'x.com', 'twitter.com', 'threads.net', 'threads.com', 'facebook.com'];
  const wl = whitelist.map(d => String(d).toLowerCase());
  const social = SOCIAL.filter(d => !wl.some(w => w.includes(d) || d.includes(w)));

  const exclude = (blacklist.length > 0 ? blacklist : ['wikipedia.org']).concat(social);
  body.exclude_domains = [...new Set(exclude)];

  return body;
})() }}

