const items = $input.all();
const find = (key) => items.find(i => i.json.output?.[key] !== undefined)?.json.output?.[key] || [];

return [{ json: {
  ingPileups:           find('ingPileups').map(i => i.sentence),
  parallelSeries:       find('parallelSeries').map(i => i.sentence),
  hedging:              find('hedging').map(i => i.sentence),
  negativeParallelisms: find('negativeParallelisms').map(i => i.sentence),
  tailingNegations:     find('tailingNegations').map(i => i.sentence)
}}];

const item = $input.first().json;
const pageText = item.output?.editedPage || item.editedPage || '';

if (!pageText) {
  throw new Error('No page text found in input. Expected output.editedPage or editedPage.');
}

const cleaned = pageText
  .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1')
  .replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, '')
  .replace(/<(https?:\/\/[^\s>]+)>/g, '')
  .replace(/(?<![[(])(https?:\/\/[^\s)\]]+)/g, '');

return [{ json: { editedPage: cleaned } }];

const res = $input.first().json;
const prep = $('Translation Prep').first().json;
const brief = $('Brief EN').first().json;

if (!res.translations || !Array.isArray(res.translations)) {
  throw new Error(`DeepL response missing translations array. Response: ${JSON.stringify(res)}`);
}
if (res.translations.length !== prep.fieldNames.length) {
  throw new Error(`DeepL returned ${res.translations.length} translations but expected ${prep.fieldNames.length}`);
}

const decode = (str) => typeof str === 'string'
  ? str.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
       .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x2F;/g, '/')
  : str;

const t = {};
prep.fieldNames.forEach((name, i) => { t[name] = decode(res.translations[i].text); });

// The client supplied the H1 in their own language. DeepL round-tripped it,
// so restore the exact string they sent rather than a re-translation of it.
let page = t.page;
if (brief.originalH1) {
  if (/^#\s+.+$/m.test(page)) {
    page = page.replace(/^#\s+.+$/m, `# ${brief.originalH1}`);
  } else {
    page = `# ${brief.originalH1}\n\n${page}`;
  }
}

return [{ json: {
  translatedPage: page,
  translatedUserPrompt: t.userPromptTemplate.replace('{{PAGE_PLACEHOLDER}}', page),
  translatedSystemPrompt: t.systemPrompt,
  translatedTavilyQueryDescription: t.tavilyQueryDescription,
  translatedTavilyToolDescription: t.tavilyToolDescription
} }];

