let page = j.output?.citedPage || j.output?.editedPage || j.citedPage || j.editedPage || '';
if (!page) throw new Error('Page Ready: no page found. Keys: ' + Object.keys(j));

// Belt and braces: the H1 on the finished page is always the one the client sent.
const wantedH1 = brief.originalH1 || brief.h1;
if (wantedH1) {
  if (/^#\s+.+$/m.test(page)) {
    page = page.replace(/^#\s+.+$/m, `# ${wantedH1}`);
  } else {
    page = `# ${wantedH1}\n\n${page}`;
  }
}

return [{ json: { page } }];

const item = $input.first().json;
const pageText = item.output?.linksPage || item.linksPage || '';
if (!pageText) throw new Error('SEO Check: no page text found.');

const brief = $('Brief EN').first().json;

// After localisation the page is in the target language, so count the keywords
// the client actually supplied rather than the English working copies.
const coreKeyword = String(brief.isLang ? brief.originalCoreKeyword : brief.coreKeyword).trim().toLowerCase();
const secondaryKeywords = String(brief.isLang ? brief.originalSecondaryKeywords : brief.secondaryKeywords)
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const countKW = kw => kw ? (pageText.toLowerCase().match(new RegExp(esc(kw), 'g')) || []).length : 0;

const totalWords = pageText.split(/\s+/).filter(w => w.length > 0).length;
const title = (pageText.match(/^#\s+(.+)$/m) || [])[1] || '';
const h2Lines = [...pageText.matchAll(/^##\s+(.+)$/gm)].map(m => m[1].toLowerCase());
const h3Lines = [...pageText.matchAll(/^###\s+(.+)$/gm)].map(m => m[1].toLowerCase());
const allHeadings = [...h2Lines, ...h3Lines];

const bodyWords = pageText.replace(/^#\s+.+$/m, '').toLowerCase()
  .replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
const first60 = bodyWords.slice(0, 60).join(' ');

// Landing pages run shorter and denser than articles, so the bands differ on purpose.
const CORE_MIN = 0.006, CORE_MAX = 0.018, CORE_TARGET = 0.010;
const SEC_MIN  = 0.0015, SEC_MAX = 0.006, SEC_TARGET = 0.003;

const coreCount = countKW(coreKeyword);
const corePct = totalWords > 0 ? coreCount / totalWords : 0;

const edits = [];

if (coreKeyword && corePct < CORE_MIN) {
  const target = Math.max(coreCount + 1, Math.ceil(totalWords * CORE_TARGET));
  edits.push({ action: 'inject', type: 'core', keyword: coreKeyword, currentCount: coreCount, targetCount: target, diff: target - coreCount, placement: 'anywhere it reads naturally' });
} else if (coreKeyword && corePct > CORE_MAX) {
  const target = Math.ceil(totalWords * CORE_TARGET);
  edits.push({ action: 'remove', type: 'core', keyword: coreKeyword, currentCount: coreCount, targetCount: target, diff: coreCount - target, placement: 'wherever it affects the copy least, never in a heading' });
}

const secondaryStats = secondaryKeywords.map(kw => {
  const count = countKW(kw);
  const pct = totalWords > 0 ? count / totalWords : 0;
  if (pct < SEC_MIN) {
    const target = Math.max(count + 1, Math.ceil(totalWords * SEC_TARGET));
    edits.push({ action: 'inject', type: 'secondary', keyword: kw, currentCount: count, targetCount: target, diff: target - count, placement: 'anywhere it reads naturally' });
  } else if (pct > SEC_MAX) {
    const target = Math.ceil(totalWords * SEC_TARGET);
    edits.push({ action: 'remove', type: 'secondary', keyword: kw, currentCount: count, targetCount: target, diff: count - target, placement: 'wherever it affects the copy least, never in a heading' });
  }
  return { keyword: kw, count, percentage: +(pct * 100).toFixed(2), inHeading: allHeadings.some(h => h.includes(kw)) };
});

const coreInFirst60 = coreKeyword ? first60.includes(coreKeyword) : false;
if (coreKeyword && !coreInFirst60) {
  edits.push({ action: 'inject', type: 'core', keyword: coreKeyword, currentCount: coreCount, targetCount: coreCount + 1, diff: 1, placement: 'inside the first 60 words, in the outcome sentence or the opening answer paragraph' });
}

const lines = pageText.split('\n');
let listsCount = 0, inList = false;
for (const line of lines) {
  const isItem = /^\s*[-*+]\s|^\s*\d+\.\s/.test(line);
  if (isItem && !inList) { listsCount++; inList = true; }
  else if (!isItem && line.trim()) { inList = false; }
}

return [{ json: {
  totalWords,
  coreKeyword,
  coreCount,
  corePercentage: +(corePct * 100).toFixed(2),
  secondaryKeywords: secondaryStats,
  // headings are locked downstream, so placement is reported and never auto-edited
  structural: {
    coreInH1: coreKeyword ? title.toLowerCase().includes(coreKeyword) : false,
    coreInAnyH2: coreKeyword ? h2Lines.some(h => h.includes(coreKeyword)) : false,
    coreInFirst60,
    anySecondaryInHeading: secondaryStats.some(s => s.inHeading),
    h2Count: h2Lines.length,
    h3Count: h3Lines.length
  },
  listsCount,
  edits
} }];

